if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('/sw.js');
}

const VERSION = 'v1';
const CACHE_CASCARON = 'cascaron-' + VERSION;
const CACHE_DATOS = 'datos';
const CASCARON = ['/index.html', '/app.js', '/estilo.css', '/manifest.webmanifest', '/icono-192.png'];

self.addEventListener('install', (evento) => {
  evento.waitUntil(caches.open(CACHE_CASCARON).then((c) => c.addAll(CASCARON)));
});

self.addEventListener('activate', (evento) => {
  evento.waitUntil(
    caches.keys().then((nombres) =>
      Promise.all(nombres.filter((n) => n.startsWith('cascaron-') && n !== CACHE_CASCARON).map((n) => caches.delete(n)))
    )
  );
});

self.addEventListener('fetch', (evento) => {
  const url = new URL(evento.request.url);
  if (evento.request.method !== 'GET' || url.origin !== location.origin) return;
  if (url.pathname.startsWith('/api/')) {
    // primero la red; si falla, lo último que guardamos
    evento.respondWith(
      fetch(evento.request)
        .then((r) => { const copia = r.clone(); evento.waitUntil(caches.open(CACHE_DATOS).then((c) => c.put(evento.request, copia))); return r; })
        .catch(async () => {
          const guardada = await caches.match(evento.request);
          if (!guardada) return new Response('sin datos', { status: 503 });
          const h = new Headers(guardada.headers); h.set('x-origen', 'cache');
          return new Response(guardada.body, { status: 200, headers: h });
        })
    );
    return;
  }
  // el cascarón: primero la caché
  evento.respondWith(caches.match(evento.request, { ignoreSearch: true }).then((c) => c || fetch(evento.request)));
});

// la página pide, con un mensaje, que la versión nueva tome el control sin esperar
self.addEventListener('message', (evento) => {
  if (evento.data === 'skipWaiting') self.skipWaiting();
});

